-- The 2026 organisations and POMs from epr-calculator-api's integration tests (src/EPR.Calculator.API.IntegrationTests/TestData). The calculator only reads these tables as they stand when CommonDataApi__DataLoader__Enabled is false; otherwise a run refills them from epr-common-data-api.
-- Matches the dev environments, so a read doesn't block behind a run's long write transaction.
IF NOT EXISTS (SELECT 1 FROM sys.databases WHERE database_id = DB_ID() AND is_read_committed_snapshot_on = 1)
    ALTER DATABASE CURRENT SET READ_COMMITTED_SNAPSHOT ON WITH ROLLBACK IMMEDIATE;

TRUNCATE TABLE data_api_load_organisations;

TRUNCATE TABLE data_api_load_poms;
